import java.util.Scanner;

public class Main {
    static final int N = 505;
    static int n, m, mod;
    static int[][] C = new int[N][N];
    static long[] f = new long[N], g = new long[N];
    static long[][] ff = new long[N][N], gg = new long[N][N];

    static void safeAdd(long[] array, int index, long y) {
        array[index] += y;
        if (array[index] >= mod) {
            array[index] -= mod;
        }
    }

    static void safeAdd2(long[][] array, int i, int j, long y) {
        array[i][j] += y;
        if (array[i][j] >= mod) {
            array[i][j] -= mod;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }

        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long val1 = (f[j - 1] * f[i - j]) % mod;
                val1 = (val1 * C[i - 1][j - 1]) % mod;
                val1 = (val1 * (i + 1)) % mod;
                safeAdd(f, i, val1);

                long val2 = (g[j - 1] * f[i - j]) % mod;
                val2 = (val2 * C[i - 1][j - 1]) % mod;
                val2 = (val2 * (i + 1)) % mod;
                safeAdd(g, i, val2);

                long val3 = (g[i - j] * f[j - 1]) % mod;
                val3 = (val3 * C[i - 1][j - 1]) % mod;
                val3 = (val3 * (i + 1)) % mod;
                safeAdd(g, i, val3);

                int s = 0;
                for (int k = 1; k <= i; k++) {
                    s += Math.abs(k - j);
                }
                long val4 = (f[j - 1] * f[i - j]) % mod;
                val4 = (val4 * C[i - 1][j - 1]) % mod;
                val4 = (val4 * s) % mod;
                safeAdd(g, i, val4);
            }
        }

        ff[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == i) {
                    ff[i][j] = f[i];
                    gg[i][j] = g[i];
                    continue;
                }
                ff[i][j] = ff[i - 1][j];
                gg[i][j] = gg[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    long valF = (ff[i - k - 1][j - k] * f[k]) % mod;
                    valF = (valF * C[j][k]) % mod;
                    safeAdd2(ff, i, j, valF);

                    long valG1 = (ff[i - k - 1][j - k] * g[k]) % mod;
                    valG1 = (valG1 * C[j][k]) % mod;
                    safeAdd2(gg, i, j, valG1);

                    long valG2 = (gg[i - k - 1][j - k] * f[k]) % mod;
                    valG2 = (valG2 * C[j][k]) % mod;
                    safeAdd2(gg, i, j, valG2);
                }
            }
        }

        System.out.println(gg[n][m]);
        sc.close();
    }
}
